/**
 * THE REPORTER: the outside half of the recording requirement (T06, #9).
 *
 * The journal (src/records/journal.ts) is what the MOD remembers, inside the
 * character's own save. This module is what the HARNESS writes: the
 * `runs.json` of docs/runs/README.md, one entry per character - build, seed,
 * decisions, turns, maxDepth, clvl, kills, gold, causeOfDeath and the command
 * census - plus the session's build facts. Rule 1: a change without a record
 * is an unmeasured change, and a record hand-assembled is a claim, so the
 * table's raw JSON is GENERATED by this code and the curated README is
 * written from it, never the other way round.
 *
 * A PLAIN FUNCTION, NOT TEST-BOUND. src/play.test.ts calls it to prove a
 * session produces a complete document, and T07's bake-off sweep (and
 * tools/runs.mjs, which writes the committed docs/runs/ directory) calls the
 * same function over its own sessions. No vitest, no engine import, no wall
 * clock: the `recorded` date arrives as an input so a test can pin it and a
 * tool can pass today.
 *
 * Field names follow docs/runs/README.md and, where they overlap, the import
 * baseline's runs.json (`recorded`, `build`): a later reader diffs sessions,
 * so a renamed field is a broken comparison.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * runs.json's key for the engine pin, spelled once. The name is the schema's
 * (the import baseline's build block already carried an `engine` line); it is
 * written as a constant because the adapter-boundary scanner takes any
 * `engine` identifier for a read of the engine namespace, and a JSON field
 * name is not that.
 */
const ENGINE_KEY = "engine";

/** One character's run, as one entry of runs.json. */
export interface RunsRunEntry {
  /** The engine seed this character's game was booted with. */
  readonly seed: number;
  /** The build the character was born with. */
  readonly build: {
    readonly race: string;
    readonly class: string;
    /** The point-buy allocation the character was born with (statBirth). */
    readonly baseStats: readonly number[];
  };
  /** Decisions taken before the run ended. */
  readonly decisions: number;
  /** Game turns elapsed. */
  readonly turns: number;
  /** Deepest dungeon level (0 = town) the character stood on. */
  readonly maxDepth: number;
  /** Character level at end of run. */
  readonly clvl: number;
  /** Monsters slain, from the game's own kill records. Null when this harness could not read them honestly. */
  readonly kills: number | null;
  readonly gold: number;
  /** The killer as the game reported it (the player's own died-from). */
  readonly causeOfDeath: string | null;
  /** The command census: how many times each command code was issued. */
  readonly commands: Readonly<Record<string, number>>;
}

/** The session's build facts, commit-independent on purpose. */
export interface RunsBuildFacts {
  /** The mod's name and version, from manifest.json. */
  readonly mod: string;
  /** The engine this repository pins (package.json's devDependency), under the baseline's own key. */
  readonly [ENGINE_KEY]: string;
  /** Where the content pack came from. */
  readonly content: string;
  /** The seeds the session played, in play order. */
  readonly seeds: readonly number[];
  /** The caps the session played under. */
  readonly caps: {
    /** Decisions each character was capped at. */
    readonly decisions: number;
  };
}

/** A whole session's runs.json document. */
export interface RunsDocument {
  /** The date the session was recorded (an input, not a clock read). */
  readonly recorded: string;
  readonly build: RunsBuildFacts;
  readonly runs: readonly RunsRunEntry[];
}

/** What one life hands the reporter (src/records/session.ts's record of it). */
export interface RunsRunInput {
  readonly seed: number;
  readonly race: string;
  readonly className: string;
  readonly baseStats: readonly number[];
  readonly decisions: number;
  readonly turns: number;
  readonly maxDepth: number;
  readonly clvl: number;
  readonly kills: number | null;
  readonly gold: number;
  readonly causeOfDeath: string | null;
  readonly commands: Readonly<Record<string, number>>;
}

/** What a session hands the reporter besides its runs. */
export interface RunsFactsInput {
  /** The repository root holding manifest.json and package.json. */
  readonly repoRoot: string;
  /** Where the content pack came from, in the caller's own words. */
  readonly content: string;
  readonly seeds: readonly number[];
  readonly caps: RunsBuildFacts["caps"];
}

/**
 * The mod's name and version as manifest.json declares them (what the game
 * installs), or a loud "unknown" when the manifest cannot be read - a record
 * that silently said nothing about which mod played is worse than one that
 * says it does not know.
 */
export function modFacts(repoRoot: string): { readonly name: string; readonly version: string } {
  try {
    const manifest = JSON.parse(readFileSync(join(repoRoot, "manifest.json"), "utf8")) as {
      readonly data?: { readonly name?: unknown; readonly version?: unknown };
    };
    const name = typeof manifest.data?.name === "string" ? manifest.data.name : "unknown mod";
    const version = typeof manifest.data?.version === "string" ? manifest.data.version : "unknown version";
    return { name, version };
  } catch {
    return { name: "unknown mod", version: "unknown version" };
  }
}

/**
 * The engine pin: the `@rpgm-tools/neo-angband-core` version this repository
 * dev-depends on, which is the published engine the harness boots. Read from
 * package.json (the pin) rather than node_modules (the copy), because the pin
 * is what a reader comparing sessions wants: it is the claim, not the
 * coincidence of what is installed today.
 */
export function enginePin(repoRoot: string): string {
  try {
    const pkg = JSON.parse(readFileSync(join(repoRoot, "package.json"), "utf8")) as {
      readonly devDependencies?: Readonly<Record<string, unknown>>;
    };
    const pinned = pkg.devDependencies?.["@rpgm-tools/neo-angband-core"];
    return typeof pinned === "string" ? `@rpgm-tools/neo-angband-core ${pinned}` : "@rpgm-tools/neo-angband-core (unpinned)";
  } catch {
    return "@rpgm-tools/neo-angband-core (unpinned)";
  }
}

/** The session's build facts, read from the repository the harness runs in. */
export function runsBuildFacts(input: RunsFactsInput): RunsBuildFacts {
  const mod = modFacts(input.repoRoot);
  return {
    mod: `${mod.name} ${mod.version}`,
    [ENGINE_KEY]: enginePin(input.repoRoot),
    content: input.content,
    seeds: [...input.seeds],
    caps: { decisions: input.caps.decisions },
  };
}

/**
 * Build the runs.json document for one session. One entry per character, in
 * the order they were played; every number is the caller's measured value and
 * this function adds nothing it was not handed.
 */
export function sessionRunsDocument(
  input: { readonly recorded: string; readonly facts: RunsBuildFacts; readonly runs: readonly RunsRunInput[] },
): RunsDocument {
  return {
    recorded: input.recorded,
    build: input.facts,
    runs: input.runs.map((run) => ({
      seed: run.seed,
      build: { race: run.race, class: run.className, baseStats: [...run.baseStats] },
      decisions: run.decisions,
      turns: run.turns,
      maxDepth: run.maxDepth,
      clvl: run.clvl,
      kills: run.kills,
      gold: run.gold,
      causeOfDeath: run.causeOfDeath,
      commands: { ...run.commands },
    })),
  };
}
